const fixture = (index = 1): IOptionEWorkplanDraftV3Aggregate => JSON.parse(fixtures[index].body) as IOptionEWorkplanDraftV3Aggregate;
describe('private V3 partial content contract', () => {
    test.each(fixtures)('admits issued $name without changing source content', ({ body }) => {
        const input: unknown = JSON.parse(body);
        const before = JSON.stringify(input);
        expect(() => validateOptionEPartialDraftV3Aggregate(input)).not.toThrow();
        expect(JSON.stringify(input)).toBe(before);
    });
    test('admits empty unfinished sections and absent reference claims', () => {
        const input = fixture(0);
        input.impact = [];
        expect(() => validateOptionEPartialDraftV3Aggregate(input)).not.toThrow();
    });
    test.each([
        ['AccountableOwner', 'Owner'], ['DeliveryLead', 'Delivery'], ['Contributor', 'Delivery'],
        ['Oversight', 'Support'], ['EvidenceProvider', 'Support']
    ] as const)('retains native %s in its %s family', (nativeRole, role) => {
        const input = fixture();
        input.core.entries[0].nativeRole = nativeRole;
        input.core.entries[0].role = role;
        expect(() => validateOptionEPartialDraftV3Aggregate(input)).not.toThrow();
        expect(input.core.entries[0].nativeRole).toBe(nativeRole);
    });
    test('rejects crossed native/editor families and unknown alias', () => {
        const input = fixture();
        input.core.entries[0].role = 'Support';
        expect(() => validateOptionEPartialDraftV3Aggregate(input)).toThrow();
        expect(() => validateOptionEPartialDraftV3Aggregate({ ...input, core: { ...input.core,
                entries: [{ ...input.core.entries[0], nativeRole: 'Unknown' }] } })).toThrow();
    });
    test.each(['core', 'impact'] as const)('rejects duplicate %s logical identities', section => {
        const input = fixture();
        if (section === 'core')
            input.core.entries.push({ ...input.core.entries[0] });
        else
            input.impact.push({ ...input.impact[0] });
        expect(() => validateOptionEPartialDraftV3Aggregate(input)).toThrow();
    });
    test('rejects repeated native quarter order without silently dropping entries', () => {
        const input = fixture();
        input.core.entries[0].nativeQuarterOrder = ['Q1', 'Q1'];
        expect(() => validateOptionEPartialDraftV3Aggregate(input)).toThrow();
    });
    test.each([-0, Infinity, NaN, -1, 101])('rejects invalid stored percentage %p', weight => {
        const input = fixture();
        input.impact[0].personalItemWeight = weight;
        expect(() => validateOptionEPartialDraftV3Aggregate(input)).toThrow();
    });
    test('rejects an undeclared target representation field', () => {
        const input = fixture();
        const malformed = { ...input, core: { ...input.core, entries: [{ ...input.core.entries[0], targets: {
                            ...input.core.entries[0].targets, annual: { kind: 'Scalar', numericValue: 0 }
                        } }] } };
        expect(() => validateOptionEPartialDraftV3Aggregate(malformed)).toThrow();
    });
    test.each(['Incomplete', 'RetainedUnresolved'] as const)('requires an actual selection for %s', state => {
        const input = fixture(0);
        input.impact[0].classification = { state };
        expect(() => validateOptionEPartialDraftV3Aggregate(input)).toThrow();
        input.impact[0].classification = { state, strategicPillar: { key: 'HISTORIC-PILLAR', label: '' } };
        expect(() => validateOptionEPartialDraftV3Aggregate(input)).not.toThrow();
    });
    test('rejects pinned selection whose historic taxonomy version disagrees', () => {
        const input = fixture(2);
        const claim = input.impact[0].classification;
        if (claim.state !== 'Pinned')
            throw new Error('Fixture is not pinned');
        claim.businessContributionArea.taxonomyVersion = 'current-unrelated';
        expect(() => validateOptionEPartialDraftV3Aggregate(input)).toThrow();
    });
    test.each(['W/"weak"', '"*"', 'unquoted'])('rejects malformed full pin ETag %s', etag => {
        const input = fixture(2);
        const claim = input.impact[0].classification;
        if (claim.state !== 'Pinned')
            throw new Error('Fixture is not pinned');
        claim.taxonomyPin.etag = etag;
        expect(() => validateOptionEPartialDraftV3Aggregate(input)).toThrow();
    });
    test('rejects crossed Behaviour snapshots while retaining partial empty commitments', () => {
        const input = fixture(2);
        input.behaviours.governedExtension!.headlines[2].selections[0].catalogueRevision = 2;
        expect(() => validateOptionEPartialDraftV3Aggregate(input)).toThrow();
    });
    test('rejects legacy guidance mismatch and non-prefix Behaviour order', () => {
        const input = fixture();
        input.behaviours.entries[0].selectedPromptKeys = ['missing-guidance'];
        expect(() => validateOptionEPartialDraftV3Aggregate(input)).toThrow();
        input.behaviours.entries[0].selectedPromptKeys = [];
        input.behaviours.entries[0].valueId = 'BHV-02';
        expect(() => validateOptionEPartialDraftV3Aggregate(input)).toThrow();
    });
    test('checks copied Overall weights without making them employee authority', () => {
        const input = fixture();
        input.referenceClaims!.overallDelivery!.impactWeight = 29;
        expect(() => validateOptionEPartialDraftV3Aggregate(input)).toThrow();
    });
    test.each(['personKey', 'managerPersonKey', 'approved', 'nativeAvailable'])('rejects undeclared root authority field %s', key => {
        expect(() => validateOptionEPartialDraftV3Aggregate({ ...fixture(), [key]: 'untrusted' })).toThrow();
    });
});
